using Godot;
using System;
using System.Collections.Generic;
public partial class MigrationScene {
 double nextChop,nextPath;
 void StreamTerrain(bool immediate=false){if(CoopHost){StreamCoopTerrain(immediate);return;}int cx=ExpeditionWorld.Cell(player.Position.X),cz=ExpeditionWorld.Cell(player.Position.Z),budget=immediate?49:2;ArtHorizon(cx,cz);var dead=new List<(int,int)>();foreach(var pair in chunks)if(Math.Abs(pair.Key.Item1-cx)>3||Math.Abs(pair.Key.Item2-cz)>3)dead.Add(pair.Key);foreach(var key in dead){terrainRoot.RemoveChild(chunks[key]);chunks[key].QueueFree();chunks.Remove(key);props.RemoveAll(p=>(p.Kind==0||p.Kind==7)&&ExpeditionWorld.Cell(p.Position.X)==key.Item1&&ExpeditionWorld.Cell(p.Position.Z)==key.Item2);}for(int r=0;r<=3;r++)for(int dx=-r;dx<=r;dx++)for(int dz=-r;dz<=r;dz++){if(Math.Max(Math.Abs(dx),Math.Abs(dz))!=r||budget<=0)continue;var key=(cx+dx,cz+dz);if(chunks.ContainsKey(key)||!game.World.InBlock(key.Item1*64+32,key.Item2*64+32))continue;chunks[key]=CreateChunk(key.Item1,key.Item2);budget--;}}
 Node3D CreateChunk(int cx,int cz,bool simulationOnly=false){var root=new Node3D{Name="Chunk_"+cx+"_"+cz};root.SetMeta("simulation_only",simulationOnly);terrainRoot.AddChild(root);var mesh=new SurfaceTool();mesh.Begin(Mesh.PrimitiveType.Triangles);for(int x=cx*64;x<(cx+1)*64;x+=4)for(int z=cz*64;z<(cz+1)*64;z+=4){Vector3 a=Ground(x,z),b=Ground(x+4,z),c=Ground(x+4,z+4),d=Ground(x,z+4);Color color=game.World.IsRiver(x+2,z+2)?new Color(.12f,.25f,.31f):(game.World.Changes.OnPath(x+2,z+2)||Math.Abs(x+2-game.World.RouteX(z+2))<5)?(game.World.Tier(x,z)<=2?new Color(.10f,.08f,.045f):new Color(.075f,.07f,.058f)):new Color(.12f,.18f,.095f);foreach(var v in new[]{a,b,c,a,c,d}){mesh.SetColor(color);mesh.AddVertex(v);}}mesh.GenerateNormals();var terrain=mesh.Commit();var terrainMat=TerrainInk();var mi=new MeshInstance3D{Mesh=terrain,MaterialOverride=terrainMat};if(!simulationOnly)root.AddChild(mi);else mi.Free();var groundBody=new StaticBody3D();groundBody.AddToGroup("terrain");groundBody.AddChild(new CollisionShape3D{Shape=terrain.CreateTrimeshShape()});root.AddChild(groundBody);
 var random=new Random(unchecked((int)game.World.Hash(cx,cz)));for(int i=0;i<24;i++){double px=cx*64+random.NextDouble()*64,pz=cz*64+random.NextDouble()*64;int tier=game.World.Tier(px,pz);if(!game.World.Playable(px,pz)||Math.Abs(px-game.World.RouteX(pz))<8||(tier>=3&&(i>3||game.World.BuildingCell(Math.Floor(px/32)*32+16,Math.Floor(pz/32)*32+16)))||px*px+pz*pz<324||tier==1&&i>2)continue;bool clear=false;foreach(var e in ExpeditionDungeon.Nearby(game.World,px,pz))if(ExpeditionGame.Distance(px,pz,e.X,e.Z)<12)clear=true;if(clear)continue;bool tree=random.NextDouble()<.87;double h=tree?7+random.NextDouble()*8:1.5;string id="block1/"+game.Save.Seed+"/tree/"+cx+":"+cz+"/"+i;if(game.World.Changes.Cut(id))continue;var p=new WorldProp{Id=id,Position=Ground(px,pz),Kind=tree?0:7,Tier=tier,Node=new Node3D{Position=Ground(px,pz)}};root.AddChild(p.Node);props.Add(p);if(simulationOnly){if(tree)PhysicsObstacle(p.Node,new CylinderShape3D{Radius=.45f,Height=(float)h*.65f},new Vector3(0,(float)h*.325f,0));else PhysicsObstacle(p.Node,new SphereShape3D{Radius=1},new Vector3(0,.45f,0));}else if(tree)ArtTree(p.Node,(float)h,unchecked((int)game.World.Hash((int)px,(int)pz)));else{Ellipsoid(p.Node,new Vector3(0,.55f,0),new Vector3(1,.7f,.85f),new Color(.42f,.43f,.36f));var rockBody=new StaticBody3D();rockBody.AddChild(new CollisionShape3D{Shape=new SphereShape3D{Radius=1},Position=new Vector3(0,.45f,0)});p.Node.AddChild(rockBody);}}

 for(int x=cx*64+16;x<(cx+1)*64;x+=32)for(int z=cz*64+16;z<(cz+1)*64;z+=32)if(game.World.BuildingCell(x,z)){float size=(float)game.World.BuildingHalf(x,z)*2,h=(float)game.World.BuildingHeight(x,z);if(simulationOnly)PhysicsObstacle(root,new BoxShape3D{Size=new Vector3(size,h,size)},Ground(x,z)+new Vector3(0,h/2,0));else ArtBuilding(root,x,z,size,h,game.World.Tier(x,z));}
 WorldDetails(root,cx,cz,simulationOnly);if(simulationOnly)SimulationStreetCollisions(root,cx,cz);if(!simulationOnly){ArtGrass(root,cx,cz);ArtRoad(root,cx,cz);ArtStreetside(root,cx,cz);}
 return root;}
 Vector3 Ground(double x,double z){return new Vector3((float)x,(float)game.World.Height(x,z),(float)z);}
 void RebuildTerrain(){storyScanDue=0;foreach(var n in chunks.Values){terrainRoot.RemoveChild(n);n.QueueFree();}chunks.Clear();props.RemoveAll(p=>p.Kind==0||p.Kind==7);StreamTerrain(true);}
 void InvalidateTerrain(Vector3 point){int minX=ExpeditionWorld.Cell(point.X-8),maxX=ExpeditionWorld.Cell(point.X+8),minZ=ExpeditionWorld.Cell(point.Z-8),maxZ=ExpeditionWorld.Cell(point.Z+8);for(int x=minX;x<=maxX;x++)for(int z=minZ;z<=maxZ;z++){var key=(x,z);if(!chunks.TryGetValue(key,out var node))continue;terrainRoot.RemoveChild(node);node.QueueFree();props.RemoveAll(p=>(p.Kind==0||p.Kind==7)&&ExpeditionWorld.Cell(p.Position.X)==x&&ExpeditionWorld.Cell(p.Position.Z)==z);chunks[key]=CreateChunk(x,z,CoopHost&&!LocalChunk(x,z));}}
 void SpawnObjects(){if(dungeon!=null)return;EnsureStarterCamp();SoutheastCamp();CampWorkbench();ExpeditionSupplies();SpawnStorySites();int cx=(int)Math.Round(player.Position.X/32),cz=(int)Math.Round(player.Position.Z/32);for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++){int x=(cx+dx)*32,z=(cz+dz)*32;int tier=game.World.Tier(x,z),m=tier>1?tier+1:(int)(game.World.Hash(cx+dx,cz+dz)%3);AddResource("block1/"+game.Save.Seed+"/node/"+(cx+dx)+":"+(cz+dz),x,z,m,3,tier);}for(int i=0;i<3;i++)AddResource("block1/"+game.Save.Seed+"/starter/"+i,(i-1)*5,4,i,i==0?8:6,1);
 foreach(var d in ExpeditionDungeon.Nearby(game.World,0,0)){string id="portal/"+d.Id;if(Distance(player.Position,Ground(d.X,d.Z))>220||uniqueObjects.Contains(id))continue;uniqueObjects.Add(id);var node=new Node3D{Position=Ground(d.X,d.Z)};worldRoot.AddChild(node);Box(node,new Vector3(-1.65f,1.5f,0),new Vector3(1,3,1),new Color(.33f,.37f,.35f),true);Box(node,new Vector3(1.65f,1.5f,0),new Vector3(1,3,1),new Color(.33f,.37f,.35f),true);Box(node,new Vector3(0,2.8f,0),new Vector3(4.3f,.6f,1),new Color(.28f,.32f,.30f),true);var label=new Label3D{Text=d.Name+" / T"+d.Tier,Position=new Vector3(0,3.5f,0),FontSize=28,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled};node.AddChild(label);props.Add(new WorldProp{Id=id,Kind=4,Position=node.Position,Node=node});}
 int sx=(int)Math.Floor(player.Position.X/160),sz=(int)Math.Floor(player.Position.Z/160);for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){int x=(sx+dx)*160+35,z=(sz+dz)*160+30;string id="wreck/"+(sx+dx)+":"+(sz+dz);if(!game.World.Playable(x,z)||uniqueObjects.Contains(id))continue;uniqueObjects.Add(id);bool burned=game.World.Changes.Burned(id);var node=new Node3D{Position=Ground(x,z)};worldRoot.AddChild(node);var carCollision=new StaticBody3D();carCollision.AddChild(new CollisionShape3D{Shape=new BoxShape3D{Size=new Vector3(2.1f,1.5f,4.2f)},Position=new Vector3(0,.75f,0)});node.AddChild(carCollision);ArtWreck(node,burned);props.Add(new WorldProp{Id=id,Kind=2,Position=node.Position,Hp=burned?0:100,Node=node});}
 foreach(var p in props.ToArray())if(p.Kind!=0&&p.Kind!=7&&!(CoopHost?NearActiveSurface(p.Position,300):Distance(p.Position,player.Position)<=300)){worldRoot.RemoveChild(p.Node);p.Node.QueueFree();props.Remove(p);uniqueObjects.Remove(p.Id);}SyncCampObjects();}
 void AddResource(string id,double x,double z,int material,int amount,int tier){if(uniqueObjects.Contains(id)||game.Craft.Gathered.Contains(id)||!game.World.Playable(x,z))return;uniqueObjects.Add(id);var node=new Node3D{Position=Ground(x,z)};worldRoot.AddChild(node);ArtResource(node,material);props.Add(new WorldProp{Id=id,Kind=1,Position=node.Position,Material=material,Amount=amount,Tier=tier,Node=node});}
 WorldProp NearProp(int kind,float reach=3.3f){WorldProp best=null;float d=reach;foreach(var p in props)if(p.Kind==kind&&p.Node.IsInsideTree()){float n=Distance(p.Position,player.Position);if(n<d){best=p;d=n;}}return best;}
 void ChopTree(){if(CoopClient&&game.Clock<nextChop)return;if(CoopRequest("chop")){nextChop=game.Clock+.75;return;}if(dungeon!=null||game.Clock<nextChop)return;nextChop=game.Clock+.75;var p=AimedTree();if(p==null){game.Notice="Move within reach of a tree";return;}int required=p.Tier<=2?1:p.Tier==3?3:5;if(game.Skills.Strength.Level<required){game.Notice="Hardwood needs Strength "+required;return;}if(game.Stamina<8){game.Notice="Too exhausted to chop";return;}game.Stamina-=8;Sound(4);Noise(20);WoodImpact(p);p.Hits++;if(p.Hits<Math.Max(2,4-(game.Skills.Strength.Level-1)/5)){game.Notice="Chopping / hit "+p.Hits;return;}if(game.Change(()=>{game.Skills.Strength.Gain(80);game.World.Changes.Fell(p.Id);game.World.Changes.Stumps.Add(new ExpeditionEarthPatch{X=p.Position.X,Z=p.Position.Z,Height=p.Position.Y});game.Craft.Materials[0]+=4;if(p.Tier==2){game.Craft.Materials[3]++;game.Craft.UnlockedTier=Math.Max(2,game.Craft.UnlockedTier);}})){FallingTree(p);props.Remove(p);game.Notice="Tree felled / +4 timber";}}
 bool ToolPoint(out Vector3 point){point=player.Position-camera.GlobalBasis.Z*3;point.Y=(float)game.World.Height(point.X,point.Z);if(dungeon!=null||!game.World.Playable(point.X,point.Z))return false;foreach(var p in game.Building.Pieces)if(ExpeditionGame.Distance(p.X,p.Z,point.X,point.Z)<4){game.Notice="Keep earthworks clear of foundations";return false;}foreach(var p in props)if((p.Kind==0||p.Kind==2||p.Kind==7)&&Distance(p.Position,point)<2)return false;return true;}
 void PaintPath(){if(CoopRequest("path")){nextPath=game.Clock+.35;return;}if(game.Clock<nextPath)return;nextPath=game.Clock+.35;if(!ToolPoint(out var p)||game.World.Changes.OnPath(p.X,p.Z))return;if(game.Change(()=>game.World.Changes.Path(new ExpeditionEarthPatch{X=p.X,Z=p.Z,Height=p.Y}))){InvalidateTerrain(p);game.Notice="Path cleared and levelled";}}
 void DigWell(){if(CoopRequest("well"))return;if(!ToolPoint(out var p))return;if(game.Craft.BenchTier<1||game.Craft.Materials[0]<4||game.Craft.Materials[1]<8){game.Notice="Well / bench 1, 4 timber, 8 stone";return;}foreach(var w in game.World.Changes.Wells)if(ExpeditionGame.Distance(w.X,w.Z,p.X,p.Z)<4)return;if(game.Change(()=>{game.Craft.Materials[0]-=4;game.Craft.Materials[1]-=8;game.World.Changes.Well(new ExpeditionEarthPatch{X=p.X,Z=p.Z,Height=p.Y});})){InvalidateTerrain(p);SyncCampObjects();game.Notice="Well dug / F draws water";}}
 void SyncCampObjects(){foreach(var b in game.Life.Camps)if(b.Seed==game.Save.Seed&&!uniqueObjects.Contains("bag/"+b.Id)){uniqueObjects.Add("bag/"+b.Id);var node=new Node3D{Position=Ground(b.X,b.Z)};worldRoot.AddChild(node);ArtSleepingBag(node);}for(int i=0;i<game.World.Changes.Wells.Count;i++){string id="well/"+i;if(uniqueObjects.Contains(id))continue;uniqueObjects.Add(id);var w=game.World.Changes.Wells[i];var node=new Node3D{Position=new Vector3((float)w.X,(float)w.Height,(float)w.Z)};worldRoot.AddChild(node);for(int s=-1;s<=1;s+=2){Box(node,new Vector3(s*.9f,.25f,0),new Vector3(.25f,.5f,2),new Color(.4f,.42f,.36f),true);Box(node,new Vector3(0,.25f,s*.9f),new Vector3(2,.5f,.25f),new Color(.4f,.42f,.36f),true);}Box(node,new Vector3(0,-.1f,0),new Vector3(1.5f,.05f,1.5f),new Color(.12f,.32f,.42f));}}
 bool CampSafe(ExpeditionBag b){if(!OutdoorFree(b.X,b.Z))return false;foreach(var e in infected)if(e.Hp>0&&!Peaceful(e.Id)&&Distance(e.Body.Position,Ground(b.X,b.Z))<45)return false;foreach(var p in props)if((p.Kind==0||p.Kind==2||p.Kind==7)&&Distance(p.Position,Ground(b.X,b.Z))<2)return false;return true;}
